<script setup>
import { computed, ref } from 'vue'
import { collectionStats, newWordPercent } from './model'
const props = defineProps({ lessons: Array, vocabulary: Object, completed: Array })
const emit = defineEmits(['open', 'add'])
const query = ref(''), unfinished = ref(false)
const stats = computed(() => collectionStats(props.lessons, props.vocabulary, props.completed))
const visible = computed(() => props.lessons.filter(l => l.title.toLowerCase().includes(query.value.toLowerCase()) && (!unfinished.value || !props.completed.includes(l.id))))
const next = computed(() => props.lessons.find(l => !props.completed.includes(l.id)) || props.lessons[0])
</script>
<template>
  <section class="collection-cover"><div class="cover-symbol">✦</div><div><p class="overline">ORIGINAL COLLECTION / B1–B2</p><h1>Ideas for a curious world</h1><p>人工智能、科技与科学。从三个新视角，重新认识你关心的世界。</p><button class="primary" @click="emit('open',next)">继续学习 →</button></div></section>
  <div class="collection-progress"><div><strong>{{ stats.completed }} / {{ stats.lessonCount }} 课时已完成</strong><span>{{ Math.round(stats.completed / Math.max(1,stats.lessonCount)*100) }}%</span></div><progress :value="stats.completed" :max="Math.max(1,stats.lessonCount)"></progress></div>
  <div class="collection-stats"><div><strong>{{ stats.total }}</strong><span>总词数（含重复）</span></div><div><strong>{{ stats.unique }}</strong><span>唯一词数</span></div><div><strong>{{ stats.new }}</strong><span>新词</span></div><div><strong>{{ stats.learning }}</strong><span>学习中</span></div><div><strong>{{ stats.known }}</strong><span>已掌握</span></div><div><strong>{{ stats.ignored }}</strong><span>已忽略</span></div></div>
  <div class="distribution" aria-label="唯一词汇状态分布"><span v-for="(label,key) in {new:'新词',learning:'学习中',known:'已掌握',ignored:'已忽略'}" :key="key" :class="key" :style="{width:(stats[key]/Math.max(1,stats.unique)*100)+'%'}" :title="label+' '+stats[key]"></span></div>
  <div class="collection-tools"><h2>合集课时</h2><input v-model="query" placeholder="搜索课时标题…" aria-label="搜索合集课时"><label><input type="checkbox" v-model="unfinished">仅未完成</label></div>
  <div class="collection-lessons"><article v-for="(lesson,index) in visible" :key="lesson.id"><div :class="['number',lesson.color]">{{ String(index+1).padStart(2,'0') }}</div><button class="lesson-title" @click="emit('open',lesson)"><strong>{{ lesson.title }}</strong><small>{{ lesson.level }} · {{ lesson.minutes }} 分钟 · {{ newWordPercent(lesson.text,vocabulary) }}% 新词 <span v-if="completed.includes(lesson.id)">· 已完成 ✓</span></small></button><button class="secondary" @click="emit('add',lesson)">＋ 加入列表</button></article></div><p v-if="!visible.length" class="empty">没有匹配的课时，请调整搜索或筛选。</p>
</template>
